1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Scenario {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	}
17	
18	export interface ScenarioResults {
19	  results: unknown[];
20	}
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	const CURSE_SURCHARGE = 0.5;
25	
26	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
27	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
28	
29	const BASE_PREMIUMS: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const COMPONENT_TYPES = ["rune", "moonstone"];
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
43	
44	const countByType = (items: Item[]): Map<string, number> => {
45	  const counts = new Map<string, number>();
46	
47	  for (const item of items) {
48	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
49	  }
50	
51	  return counts;
52	};
53	
54	/** Exactly BLOCK_SIZE alike components form a building block. */
55	const formsBuildingBlock = (type: string, count: number): boolean =>
56	  isComponent(type) && count === BLOCK_SIZE;
57	
58	/** Alike items are priced together so a building block can be recognised. */
59	const groupBasePremium = (type: string, count: number): number =>
60	  formsBuildingBlock(type, count)
61	    ? BLOCK_BASE_PREMIUM
62	    : count * BASE_PREMIUMS[type];
63	
64	/** The policy base premium is the sum of the base premiums of its items. */
65	const policyBasePremium = (items: Item[]): number =>
66	  [...countByType(items)].reduce(
67	    (total, [type, count]) => total + groupBasePremium(type, count),
68	    0,
69	  );
70	
71	/**
72	 * Item-specific modifiers apply to the base premium of the affected item,
73	 * not to the policy total.
74	 */
75	const itemSurcharges = (items: Item[]): number =>
76	  items.reduce(
77	    (total, item) =>
78	      total + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE : 0),
79	    0,
80	  );
81	
82	/**
83	 * Modifiers are expressed as amounts added to (or subtracted from) the base
84	 * premium they apply to, so several modifiers stack additively rather than
85	 * compounding.
86	 */
87	const quotePremium = (step: QuoteStep): number => {
88	  const basePremium = policyBasePremium(step.items);
89	  const policyModifiers = basePremium * FIRST_INSURANCE_SURCHARGE;
90	
91	  return roundUp(
92	    basePremium + itemSurcharges(step.items) + policyModifiers + PROCESSING_FEE,
93	  );
94	};
95	
96	export const runScenario = (scenario: Scenario): ScenarioResults => ({
97	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
98	});
